(* [comment removed for export] *)
Definition sm (y d : Z) : Z := Z.lor y (Z.shiftr y d).

Lemma sm_bits : forall y d b, 0 <= d -> 0 <= b -> Z.testbit (sm y d) b = Z.testbit y b || Z.testbit y (b + d).
Proof.
